  #stage:focus-visible{outline:3px solid #ffd76a; outline-offset:-3px;}
  .panel{
    position:fixed; z-index:2;
    background:rgba(6,9,18,.84);
    border:1px solid rgba(143,216,255,.28);
    border-radius:14px;
    padding:.9rem 1.1rem;
  }
  .intro{
    top:clamp(.6rem,2vw,1.4rem); left:clamp(.6rem,2vw,1.4rem);
