var btnMode = document.getElementById('btnMode');
var btnColor = document.getElementById('btnColor');
var btnMotion = document.getElementById('btnMotion');
var btnHelp = document.getElementById('btnHelp');
var helpPanel = document.getElementById('help');
var btnCloseHelp = document.getElementById('btnCloseHelp');

var PALETTES = [
  { name:'달빛',   bg:'#04060d', base:195, spread:55, accent:'#8fd8ff' },
  { name:'새벽불', bg:'#0c0509', base:330, spread:70, accent:'#ff9ecb' },
  { name:'신록',   bg:'#030a07', base:135, spread:55, accent:'#9df0b8' }
];
var MODES = [
  { id:'flow',  name:'흐름' },
  { id:'text',  name:'글자' },
  { id:'orbit', name:'궤도' }
];
var TOKEN_CHARS = ['가','나','다','라','마','언','어','토','큰','빛','꿈','생','각','k','i','m','3','λ','∴','✳','0','1'];

var W=0, H=0, DPR=1;
var particles=[];
var tokens=[];
