var modeIndex=0, paletteIndex=0;
var running=true;
var reduced=false;
var time=0, lastT=0;
var pointer={x:0,y:0,active:false};

var mq = window.matchMedia('(prefers-reduced-motion: reduce)');

function say(msg){
  live.textContent='';
  setTimeout(function(){ live.textContent=msg; }, 40);
}

/* ---------- 파티클 ---------- */
function newParticle(){
  var pal = PALETTES[paletteIndex];
  return {
    x: Math.random()*W, y: Math.random()*H,
    vx:0, vy:0,
    r: 1.2 + Math.random()*1.8,
    hue: pal.base + Math.random()*pal.spread,
    tx:0, ty:0,
    orbitR: 40 + Math.random()*Math.max(60,(Math.min(W,H)/2 - 60)),
    orbitDir: Math.random()<0.5 ? -1 : 1
  };
}
function targetCount(){
  var n = Math.round((W*H)/9000);
  return Math.max(80, Math.min(320, n));
}
function ensureParticleCount(){
  var n = targetCount();
  while(particles.length<n) particles.push(newParticle());
