  var pal = PALETTES[paletteIndex];
  for(var i=0;i<particles.length;i++){
    particles[i].hue = pal.base + Math.random()*pal.spread;
  }
  ctx.fillStyle = pal.bg;
  ctx.fillRect(0,0,W,H);
}

/* ---------- "kimi-k3" 글자 좌표 추출 ---------- */
function sampleText(text){
  var off = document.createElement('canvas');
  off.width=W; off.height=H;
  var o = off.getContext('2d');
  var size = Math.max(28, Math.min(W/(text.length*0.66), H*0.34));
  o.font='700 '+size+'px ui-monospace, Consolas, monospace';
  o.textAlign='center'; o.textBaseline='middle';
  o.fillStyle='#fff';
  o.fillText(text, W/2, H/2);
  var img;
  try{ img = o.getImageData(0,0,W,H).data; }catch(err){ return []; }
  var pts=[];
  var gap = Math.max(3, Math.round(size/16));
  for(var y=0;y<H;y+=gap){
    for(var x=0;x<W;x+=gap){
      if(img[(y*W+x)*4+3] > 110) pts.push({x:x,y:y});
    }
  }
  return pts;
}
function assignTargets(){
  var pts = sampleText('kimi-k3');
  if(!pts.length) return;
  var n = particles.length;
  for(var i=0;i<n;i++){
    var t = pts[Math.floor(i*pts.length/n)];
    particles[i].tx = t.x + (Math.random()-.5)*4;
    particles[i].ty = t.y + (Math.random()-.5)*4;
  }
}

/* ---------- 크기 ---------- */
function resize(){
  DPR = Math.min(window.devicePixelRatio||1, 1.75);
  W = window.innerWidth; H = window.innerHeight;
  canvas.width = Math.round(W*DPR);
  canvas.height = Math.round(H*DPR);
  canvas.style.width = W+'px';
  canvas.style.height = H+'px';
  ctx.setTransform(DPR,0,0,DPR,0,0);
  ctx.fillStyle = PALETTES[paletteIndex].bg;
  ctx.fillRect(0,0,W,H);
  ensureParticleCount();
  if(MODES[modeIndex].id==='text') assignTargets();
}

/* ---------- 시뮬레이션 ---------- */
function step(dtF){
  var speed = reduced ? 0.22 : 1;
  time += dtF*0.016*speed;
  var mode = MODES[modeIndex].id;
  var attractR = Math.min(W,H)*0.28;
  var damp = Math.pow(0.94, dtF);
  var i, p;

  for(i=0;i<particles.length;i++){
    p = particles[i];

    if(mode==='flow'){
      var a = Math.sin(p.x*0.0021 + time*0.35) + Math.cos(p.y*0.0023 - time*0.27);
      var ang = a*Math.PI;
      p.vx += Math.cos(ang)*0.06*speed*dtF;
      p.vy += Math.sin(ang)*0.06*speed*dtF;
    } else if(mode==='text'){
      p.vx += ((p.tx-p.x)*0.018 + (Math.random()-.5)*0.08)*speed*dtF;
      p.vy += ((p.ty-p.y)*0.018 + (Math.random()-.5)*0.08)*speed*dtF;
    } else {
      var cx = pointer.active ? pointer.x : W/2;
      var cy = pointer.active ? pointer.y : H/2;
      var dxo = p.x-cx, dyo = p.y-cy;
      var dO = Math.sqrt(dxo*dxo+dyo*dyo)||1;
      var tang = 0.075*speed*p.orbitDir*dtF;
      p.vx += (-dyo/dO)*tang;
      p.vy += ( dxo/dO)*tang;
      var corr = (p.orbitR-dO)*0.0012*speed*dtF;
      p.vx += (dxo/dO)*corr;
      p.vy += (dyo/dO)*corr;
    }

    if(pointer.active){
      var dxp = pointer.x-p.x, dyp = pointer.y-p.y;
      var d2 = dxp*dxp+dyp*dyp;
      if(d2 < attractR*attractR && d2>1){
        var dP = Math.sqrt(d2);
        var f = (1 - dP/attractR) * (mode==='text' ? -0.9 : 0.35) * speed * dtF;
        p.vx += (dxp/dP)*f;
        p.vy += (dyp/dP)*f;
      }
    }

    for(var u=0;u<pulses.length;u++){
      var pu = pulses[u];
      var dxq = p.x-pu.x, dyq = p.y-pu.y;
      var dQ = Math.sqrt(dxq*dxq+dyq*dyq)||1;
      var band = Math.abs(dQ-pu.r);
      if(band<60){
        var fq=(1-band/60)*pu.power*(1-pu.life)*dtF;
        p.vx += (dxq/dQ)*fq;
        p.vy += (dyq/dQ)*fq;
      }
    }

    p.vx*=damp; p.vy*=damp;
    var v2=p.vx*p.vx+p.vy*p.vy;
    if(v2>81){ var sc=9/Math.sqrt(v2); p.vx*=sc; p.vy*=sc; }

    p.x += p.vx*dtF;
    p.y += p.vy*dtF;

    var m=12;
    if(p.x<-m)p.x=W+m; else if(p.x>W+m)p.x=-m;
    if(p.y<-m)p.y=H+m; else if(p.y>H+m)p.y=-m;
  }

  for(i=pulses.length-1;i>=0;i--){
    pulses[i].r += 7*dtF*speed;
    pulses[i].life += dtF*0.02;
    if(pulses[i].life>=1) pulses.splice(i,1);
  }
  for(i=tokens.length-1;i>=0;i--){
    var t=tokens[i];
    t.x+=t.vx*dtF; t.y+=t.vy*dtF; t.life -= dtF*0.012;
    if(t.life<=0) tokens.splice(i,1);
  }
}

